const j = (s) => JSON.stringify(s);
const arr = (a) => "[" + a.map(j).join(", ") + "]";

const lines = [
  "// AUTO-GENERATED by scripts/gen-career-guides.mjs — do not edit by hand.",
  "// Powers public, prerendered SEO pages at /career-guide/<slug>.",
  "export const CAREER_GUIDES = [",
];
for (const r of C) {
  const [slug, title, category, categorySlug, emoji, tagline, salMin, salMax, freshers, timeline, difficulty, growth, degree, skills, tools, courses, roadmap, jobs, whoHires, related, intro] = r;
  const cs = "[" + courses.map(([n, p, f]) => `{name: ${j(n)}, provider: ${j(p)}, free: ${f}}`).join(", ") + "]";
  const rm = "[" + roadmap.map(([p, f]) => `{phase: ${j(p)}, focus: ${j(f)}}`).join(", ") + "]";
  lines.push("  {");
  lines.push(`    slug: ${j(slug)}, title: ${j(title)}, category: ${j(category)}, categorySlug: ${j(categorySlug)},`);
  lines.push(`    emoji: ${j(emoji)}, tagline: ${j(tagline)},`);
  lines.push(`    salaryMin: ${salMin}, salaryMax: ${salMax}, freshersSalary: ${j(freshers)},`);
  lines.push(`    timeline: ${j(timeline)}, difficulty: ${j(difficulty)}, growth: ${j(growth)}, degreeNeeded: ${degree},`);
  lines.push(`    topSkills: ${arr(skills)},`);
  lines.push(`    tools: ${arr(tools)},`);
  lines.push(`    courses: ${cs},`);
  lines.push(`    roadmap: ${rm},`);
  lines.push(`    jobTitles: ${arr(jobs)},`);
  lines.push(`    whoHires: ${arr(whoHires)},`);
  lines.push(`    related: ${arr(related)},`);
  lines.push(`    intro: ${j(intro)},`);
  lines.push("  },");
}
lines.push("];");
lines.push("");
lines.push("export function getCareerGuide(slug) {");
lines.push("  return CAREER_GUIDES.find((c) => c.slug === slug) || null;");
lines.push("}");
lines.push("");

fs.writeFileSync(OUT, lines.join("\n"));

// Also emit a plain JSON sibling that build scripts (prerender, sitemap) can read
// without ESM/CJS interop headaches.
const records = C.map((r) => {
  const [slug, title, category, categorySlug, emoji, tagline, salaryMin, salaryMax, freshersSalary, timeline, difficulty, growth, degreeNeeded, topSkills, tools, courses, roadmap, jobTitles, whoHires, related, intro] = r;
  return {
    slug, title, category, categorySlug, emoji, tagline, salaryMin, salaryMax,
    freshersSalary, timeline, difficulty, growth, degreeNeeded, topSkills, tools,
    courses: courses.map(([name, provider, free]) => ({ name, provider, free })),
    roadmap: roadmap.map(([phase, focus]) => ({ phase, focus })),
    jobTitles, whoHires, related, intro,
  };
});
const JSON_OUT = path.resolve(__dirname, "../src/data/careerGuides.json");
fs.writeFileSync(JSON_OUT, JSON.stringify(records, null, 0));
console.log(`Wrote ${path.relative(process.cwd(), OUT)} + careerGuides.json with ${C.length} careers`);
